// Kunin ang raw output mula sa AI Agent
let rawOutput = $input.first().json.output || "";

// Kung ang output ay naglalaman ng tool calling log, alisin ito
if (rawOutput.includes("Calling ") && rawOutput.includes("with input:")) {
  // Extract JSON string after the tool call log
  let jsonStart = rawOutput.indexOf("{");
  if (jsonStart !== -1) {
    rawOutput = rawOutput.substring(jsonStart);
  }
}

// Subukang i-extract ang JSON gamit ang Regex
let jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
let parsedData = {};

if (jsonMatch) {
  try {
    parsedData = JSON.parse(jsonMatch[0]);
  } catch (e) {
    parsedData = {};
  }
}

let replyText = parsedData.reply || rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
let leadScore = parsedData.lead_score || "Warm";
let phone = parsedData.customer_phone || "";
let summaryText = parsedData.summary || "Interaction recorded";

// Ayusin ang new lines para sa Telegram
replyText = replyText.replace(/\\n/g, '\n');

return [{
  json: {
    reply: replyText,
    lead_score: leadScore,
    customer_phone: phone,
    summary: summaryText,
    telegram_chat_id: $("Telegram Trigger").first().json.message.chat.id
  }
}];
